import { render } from '@solidjs/web';
import { createSignal, createMemo, Loading } from 'solid-js';

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

// A stand-in for a model API that streams its answer word by word.
async function* fakeModel(topic) {
  const answer = `${topic} are great. Here is a longer answer about ${topic}, streamed one word at a time so you can read it as it arrives.`;
  for (const word of answer.split(' ')) {
    await sleep(120);
    yield word + ' ';
  }
}

function Chat() {
  const [topic, setTopic] = createSignal('Signals');
  const reply = createMemo(async () => {
    const current = topic();
    let text = '';
    for await (const word of fakeModel(current)) text += word;
    return text;
  });

  return (
    <>
      <p>
        Ask about{' '}
        <button onClick={() => setTopic('Signals')}>Signals</button>{' '}
        <button onClick={() => setTopic('Stores')}>Stores</button>
      </p>
      <Loading fallback={<p>Thinking...</p>}>
        <p>{reply()}</p>
      </Loading>
    </>
  );
}

render(() => <Chat />, document.getElementById('app'));

